1212	  //   POST   /api/knowledge/:id/move      (body-parsing — handled in handleRequest)
1213	
1214	  return null;
1215	}
1216	
1217	// ---------------------------------------------------------------------------
1218	// Static file server
1219	// ---------------------------------------------------------------------------
1220	
1221	async function serveStatic(
1222	  req: IncomingMessage,
1223	  res: ServerResponse,
1224	  port: number
1225	): Promise<void> {
1226	  const urlPath = (req.url ?? '/').split('?')[0]!;
1227	  const filePath =
1228	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
1229	
1230	  // Security: prevent path traversal outside PUBLIC_DIR
1231	  const resolved = resolve(filePath);
1232	  if (!resolved.startsWith(PUBLIC_DIR)) {
1233	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1234	    return;
1235	  }
1236	
1237	  const ext = extname(filePath);
1238	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
1239	
1240	  try {
1241	    const content = await readFile(filePath);
1242	    res.writeHead(200, {
1243	      'Content-Type': mimeType,
1244	      'Content-Length': content.length,
1245	      'Cache-Control': 'no-store',
1246	      ...corsHeaders(port),
1247	      ...securityHeaders(),
1248	    });
1249	    res.end(content);
1250	  } catch {
1251	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1252	  }
1253	}
1254	
1255	// ---------------------------------------------------------------------------
1256	// Main request handler
1257	// ---------------------------------------------------------------------------
1258	
1259	export async function handleRequest(
1260	  req: IncomingMessage,
1261	  res: ServerResponse,
1262	  ledgerRoot: string,
1263	  configPath: string,
1264	  port: number,
1265	  orchestratorLogsDir: string,
1266	  bootVersions: WorkspaceVersions | null = null
1267	): Promise<void> {
1268	  const method = req.method?.toUpperCase() ?? 'GET';
1269	  const url = req.url ?? '/';
1270	  const [path] = url.split('?') as [string];
1271	  const segments = path.split('/').filter(Boolean);
1272	  const isApiRequest = segments[0] === 'api';
1273	
1274	  // Handle OPTIONS preflight
1275	  if (method === 'OPTIONS') {
1276	    res.writeHead(200, { ...corsHeaders(port), ...securityHeaders() });
1277	    res.end();
1278	    return;
1279	  }
1280	
1281	  // Static file serving
1282	  if (!isApiRequest) {
1283	    await serveStatic(req, res, port);
1284	    return;
1285	  }
1286	
1287	  // PUT /api/config — special case: requires body parsing
1288	  if (method === 'PUT' && path === '/api/config') {
1289	    try {
1290	      const body = await readJsonBody(req);
1291	      const result = await handleUpdateConfig(configPath, body);
1292	      sendJson(res, 200, result, port);
1293	    } catch (err) {
1294	      if (err instanceof PayloadTooLargeError) {
1295	        sendError(res, 413, 'PAYLOAD_TOO_LARGE', 'Payload Too Large.', port);
1296	      } else if (err instanceof ApiError) {
1297	        sendError(res, apiErrorToStatus(err.code), err.code, err.message, port);
1298	      } else {
1299	        process.stderr.write(`[server] Unhandled error in PUT /api/config: ${String(err)}\n`);
1300	        sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred.', port);
1301	      }
1302	    }
1303	    return;
1304	  }
1305	
1306	  // GET /api/server-info — special case: needs bootVersions closure from main()
1307	  if (method === 'GET' && path === '/api/server-info') {
1308	    try {
1309	      const boot = bootVersions ?? captureWorkspaceVersions();
1310	      const disk = captureWorkspaceVersions();
1311	      const stale =
1312	        boot.mcpServer !== disk.mcpServer ||
1313	        boot.personas !== disk.personas ||
